def f(a,b=2,/,c=3,*args,d,e=5,**kw):return [a,b,c,args,d,e,kw]
try:f()
except TypeError as error:print(type(error).__name__)
try:f(1,2,3,**{'c':4,'d':5})
except TypeError as error:print(type(error).__name__)

